// n8n's Agent node accepts a maximum of 2 language models, so a deeper
// fallback chain is built as a retry ladder. Each tier swaps the OpenRouter slot.
// 16 Aug 2026: every id below was verified live against OpenRouter -- it exists,
// it is :free (no paid model, per the free-tier rule), and it actually returned
// a tool_call in a real request. The previous ladder had a PAID gemini tier plus
// two dead ids (gemma-4-31b-it:free rate-limited 429, ling-3.0-flash:free is
// 404 free-tier-discontinued), which is why all 4 tiers failed on live traffic.
const TIERS = [
  { orModel: 'nvidia/nemotron-3-ultra-550b-a55b:free',   groqModel: 'llama-3.3-70b-versatile' },
  { orModel: 'nvidia/nemotron-3.5-lightning:free',       groqModel: 'llama-3.3-70b-versatile' },
  { orModel: 'nvidia/nemotron-3-super-120b-a12b:free',   groqModel: 'llama-3.3-70b-versatile' },
  { orModel: 'minimax/minimax-m2.7:free',                  groqModel: 'llama-3.3-70b-versatile' }
];
const prev = $input.first().json;
const attempt = Number(prev.__attempt ?? -1) + 1;
if (attempt >= TIERS.length) {
  throw new Error('All ' + TIERS.length + ' model tiers failed. Tried: ' + TIERS.map(t=>t.orModel).join(', '));
}
return [{ json: { ...prev, __attempt: attempt, orModel: TIERS[attempt].orModel, groqModel: TIERS[attempt].groqModel } }];

const l = $('Fetch Escalated Lead').all();

// 'Return Result' is what the Silence Detector reads back through
// waitForSubWorkflow. It used to answer status:'escalated', escalated:true
// purely because a lead row had been fetched - it never looked at whether the
// escalation email, the audit row or the CRM write actually landed.
// The report reaches here two ways: on the main input from 'Delivery Report'
// (email -> Audit Log -> Mark Lead Escalated chain) and, when this node is
// re-entered from the Slack branch, by name. $('Delivery Report') THROWS when
// that node has not run, so the lookup is wrapped, and an unverified run says
// so instead of claiming success.
let d = ($input.first().json || {}).delivery || null;
if (!d) {
  try { d = $('Delivery Report').first().json.delivery || null; } catch (e) { d = null; }
}

const landed = !!d && d.status !== 'FAILED';
const base = {
  status: l.length ? (d ? (landed ? 'escalated' : 'escalation_failed') : 'escalation_unverified')
                   : 'no_match',
  escalated: l.length > 0 && landed,
  delivery: d || { status: 'UNVERIFIED', verified: [], dropped: [],
                   note: 'no Delivery Report was reachable from this branch' },
  completed_at: new Date().toISOString(),
};
return [{ json: l.length ? Object.assign({}, l[0].json, base) : base }];

// This node sits ONLY on the public webhook branch.
// 'Called by Master Router' connects straight to the next node and never
// reaches here, so the trusted sub-workflow path is untouched by this guard.
// That path is live -- execution history shows both webhook and integrated
// modes in use -- so it must not be rewired.
//
// 'Verify JWT' runs with onError = continueRegularOutput, so a rejected token
// arrives as data rather than as a failed HTTP node. Supabase GET
// /auth/v1/user returns the user object on success; no .id means rejected.
const auth = $input.first().json || {};
if (!auth.id) {
  throw new Error('Escalation rejected: unauthorized. A valid Supabase session token is required in the Authorization header.');
}

// Re-emit the ORIGINAL request untouched so the downstream node sees exactly
// the shape it saw before this guard was inserted.
return $('EscalationWebhook').all();

// Delivery Report - verify every claim the next node is about to make.
// The upstream sends run with onError:'continueRegularOutput'. A failure there
// is not an exception: n8n emits an item shaped { error: ... } on the main
// output and the run stays green. Nothing downstream ever looked at it, so the
// row written next asserted a send that may never have landed.
// The swallow is deliberate and stays. Only the unconditional claim goes.
const CLAIMED = [
  { node: 'Email: Escalation Alert (Gmail)', what: 'escalation email to the senior rep', critical: true },
  { node: 'Audit Log', what: 'audit_log row for this escalation', critical: false },
  { node: 'Mark Lead Escalated', what: 'leads.escalated_at stamped on the CRM row', critical: true },
];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  return { ...c, ok: true };
}

const results = CLAIMED.map(check);

const dropped = results.filter(r => !r.ok);
const fatal   = dropped.filter(r => r.critical);

const status = fatal.length   ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

return [{ json: {
  ...( $input.first().json || {} ),
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' \u2014 ' + r.why),
    note: dropped.length
      ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
      : 'all ' + results.length + ' claimed steps verified',
  },
} }];

